package com.loadoutstudio;
import com.google.gson.*;
import java.util.*;
import net.runelite.http.api.RuneLiteAPI;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarbitID;
import org.junit.Test;
import static org.junit.Assert.*;
public class GearingImprovementsTest {
 @Test public void unorderedIgnoresExtraItemsButNeverReusesOneForTwoSlots(){JsonObject p=SetupCodec.blank("Unordered"),actual=SetupCodec.blank("Actual");SetupCodec.setup(p).addProperty("uh",true);SetupCodec.setup(p).getAsJsonArray("inv").set(0,SetupCodec.item(100,1));SetupCodec.setup(actual).getAsJsonArray("inv").set(7,SetupCodec.item(100,1));SetupCodec.setup(actual).getAsJsonArray("inv").set(8,SetupCodec.item(200,1));assertTrue(SetupComparison.differences(p,actual,false,id->id).isEmpty());SetupCodec.setup(p).getAsJsonArray("inv").set(1,SetupCodec.item(100,1));assertTrue(SetupComparison.differences(p,actual,false,id->id).contains("inv:1"));}
 @Test public void boltPouchAndAttackOptionRoundTripAndCompare(){JsonObject p=SetupCodec.blank("Bolts"),actual=SetupCodec.blank("Actual");JsonArray pouch=SetupCodec.empty(4);pouch.set(0,SetupCodec.item(100,500));SetupCodec.setup(p).add("bp",pouch);SetupCodec.setup(p).addProperty("ao","Chop");SetupCodec.rebuildLayout(p);Set<String> differences=SetupComparison.differences(p,actual,false,id->id);assertTrue(differences.contains("bp:0"));assertTrue(differences.contains("attackOption"));SetupCodec codec=new SetupCodec(RuneLiteAPI.GSON);JsonObject copy=codec.importText(codec.inventory(p)).get(0);assertEquals("Chop",SetupCodec.setup(copy).get("ao").getAsString());assertEquals(pouch,SetupCodec.setup(copy).getAsJsonArray("bp"));}
 @Test public void absentOptionalBoltPouchDoesNotDemandEmptyingIt(){JsonObject p=SetupCodec.blank("No pouch"),actual=SetupCodec.blank("Actual");JsonArray pouch=SetupCodec.empty(4);pouch.set(0,SetupCodec.item(100,500));SetupCodec.setup(actual).add("bp",pouch);assertTrue(SetupComparison.differences(p,actual,false,id->id).isEmpty());}
 @Test public void boltTypesUseBundledMappingsWithoutHubPlugin(){assertEquals(ItemID.BOLT,GearContainers.boltId(1));assertEquals(ItemID.BARROWS_KARIL_AMMO,GearContainers.boltId(82));assertEquals(-1,GearContainers.boltId(999));assertTrue(GearContainers.isBoltVarbit(VarbitID.XBOWS_POUCH_SLOT4));assertFalse(GearContainers.isBoltVarbit(VarbitID.SPELLBOOK));}
 @Test public void sharingIsSelectiveAndImportAddsIndependentCopies(){SetupLibrary source=new SetupLibrary();SetupLibrary.Section section=new SetupLibrary.Section("Raids");source.sections.add(section);SetupLibrary.Entry one=new SetupLibrary.Entry(SetupCodec.blank("One"));one.section=section.id;source.setups.add(one);source.setups.add(new SetupLibrary.Entry(SetupCodec.blank("Unshared")));JsonObject bundle=LibraryTools.bundle(source,Collections.singleton(one.id),RuneLiteAPI.GSON);assertTrue(bundle.has("libraryBundle"));SetupLibrary incoming=SetupLibrary.read(bundle.toString(),RuneLiteAPI.GSON),target=new SetupLibrary();target.setups.add(new SetupLibrary.Entry(SetupCodec.blank("Existing")));LibraryTools.merge(target,incoming,RuneLiteAPI.GSON);assertEquals(2,target.setups.size());assertNotEquals(one.id,target.setups.get(1).id);assertNotEquals(section.id,target.sections.get(0).id);SetupCodec.setup(target.setups.get(1).portable).addProperty("name","Changed");assertEquals("One",SetupCodec.name(one.portable));}
 @Test public void replacementKeepsQuantitiesRulesNotesAndLayoutHoles(){JsonObject p=SetupCodec.blank("Upgrade");JsonObject item=SetupCodec.item(100,42);item.addProperty("f",true);item.addProperty("sc","Standard");SetupCodec.setup(p).getAsJsonArray("inv").set(2,item);SetupCodec.setup(p).addProperty("notes","Keep this");SetupCodec.rebuildLayout(p);int position=6;assertEquals(100,p.getAsJsonArray("layout").get(position).getAsInt());assertEquals(1,LibraryTools.replace(p,100,200,"Upgrade"));assertEquals(200,p.getAsJsonArray("layout").get(position).getAsInt());assertEquals(42,SetupCodec.quantity(SetupCodec.setup(p).getAsJsonArray("inv").get(2)));assertTrue(SetupCodec.setup(p).getAsJsonArray("inv").get(2).getAsJsonObject().get("f").getAsBoolean());assertEquals("Keep this",SetupCodec.setup(p).get("notes").getAsString());assertEquals(-1,p.getAsJsonArray("layout").get(position-1).getAsInt());}
 @Test public void librarySearchChecksNotesAndEveryItemContainer(){SetupLibrary.Entry entry=new SetupLibrary.Entry(SetupCodec.blank("Raid"));SetupCodec.setup(entry.portable).addProperty("notes","Bring a stamina potion");SetupCodec.setup(entry.portable).getAsJsonArray("rp").set(0,SetupCodec.item(560,1000));assertTrue(LibraryTools.matches(entry,"notes:stamina",(id,q)->false));assertTrue(LibraryTools.matches(entry,"item:560",(id,q)->false));assertTrue(LibraryTools.matches(entry,"item:death",(id,q)->id==560&&q.equals("death")));assertFalse(LibraryTools.matches(entry,"item:other",(id,q)->false));}
 @Test public void customBankMovesAreReadBackAndOtherTagsAreUntouched(){BankFilterTest.FakeBank bank=new BankFilterTest.FakeBank();bank.open=true;JsonObject p=OwnedGearTest.setup();StudioBankFilter filter=new StudioBankFilter(bank,"owned");filter.select(p);int[] old=bank.layout.clone();bank.layout[1]=bank.layout[17];bank.layout[17]=-1;JsonArray changed=filter.readChangedLayout();assertNotNull(changed);assertEquals(1,changed.get(1).getAsInt());assertNull(filter.readChangedLayout());bank.active="another-tag";bank.layout=old;assertNull(filter.readChangedLayout());}
}
